{
  "missionStatement": "Study recent literature on room-temperature superconductivity and update the repository's documents to propose a comprehensive chemistry and physics framework for discovering and manufacturing room-temperature superconducting compounds.",
  "criteria": [
    {
      "description": "Literature review updated with at least 10 new references from 2020-2025 on room-temperature superconductivity, including key papers on hydrides, nickelates, and other systems.",
      "expectedFiles": ["literature_review.md"]
    },
    {
      "description": "Theoretical framework document expanded to cover BCS theory, Eliashberg theory, strong-coupling superconductivity, and the role of high pressure in hydride superconductors.",
      "expectedFiles": ["theoretical_framework.md"]
    },
    {
      "description": "Candidate materials document updated with a curated list of at least 5 promising room-temperature superconductor candidates (e.g., H3S, LaH10, YH6) including their predicted Tc, synthesis conditions, and experimental status.",
      "expectedFiles": ["candidate_materials.md"]
    },
    {
      "description": "Synthesis methods document updated to include high-pressure synthesis techniques (diamond anvil cell, laser heating), chemical doping, and thin-film growth methods relevant to room-temperature superconductors.",
      "expectedFiles": ["synthesis_methods.md"]
    },
    {
      "description": "Characterization techniques document updated to describe standard measurements (resistivity, magnetic susceptibility, specific heat, Meissner effect) and how to identify room-temperature superconductivity.",
      "expectedFiles": ["characterization_techniques.md"]
    },
    {
      "description": "Discovery strategy document updated to outline a systematic approach: computational screening (DFT, machine learning), synthesis, characterization, and feedback loop.",
      "expectedFiles": ["discovery_strategy.md"]
    },
    {
      "description": "Proposed chemistry and physics document rewritten to present a coherent theory and experimental plan for room-temperature superconductivity, including specific chemical families (e.g., hydrogen-rich compounds under pressure, nickelates) and the underlying physics (electron-phonon coupling, magnetic mechanisms).",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Roadmap document updated with concrete milestones for the next 6-12 months, including literature review completion, computational screening, synthesis attempts, and characterization.",
      "expectedFiles": ["roadmap.md"]
    },
    {
      "description": "All existing unit tests in tests/ pass without errors.",
      "expectedFiles": []
    },
    {
      "description": "Script predict_tc.py updated to include new models or data from the study (e.g., support for hydride Tc prediction using Allen-Dynes formula).",
      "expectedFiles": ["scripts/predict_tc.py"]
    },
    {
      "description": "Data file superconductor_database.json updated with new entries from literature (e.g., Tc, pressure, composition).",
      "expectedFiles": ["data/superconductor_database.json"]
    }
  ]
}

